const MODEL = String($env.ANTHROPIC_MODEL || 'claude-sonnet-5').trim();
const BUSINESS = String($env.BUSINESS_NAME || 'our clinic').trim();
const ABOUT = String($env.BUSINESS_ABOUT || '').trim();
const VISIT = String($env.VISIT_NAME || 'appointment').trim();
const POLICY = String($env.NO_SHOW_POLICY_TEXT || '').trim();
const SLOT_DAYS = Math.min(Math.max(Math.floor(num($env.SLOT_SEARCH_DAYS, 7)), 1), 30);
const SAME_STAFF = String($env.SAME_STAFF ?? 'true').trim().toLowerCase() !== 'false';
const MAX_AI = Math.max(Math.floor(num($env.MAX_AI_REPLIES, 4)), 1);

// ---- time zones and labels ----
const validTz = tz => { if (!tz || typeof tz !== 'string') return false; try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch (e) { return false; } };
const localHour = (tz, at) => Number(new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', hourCycle: 'h23' }).format(at || new Date())) % 24;
// Newer Node versions put a narrow no break space before AM/PM. SMS should only carry plain spaces.
