// A won opportunity is a past sale and is never touched. Order: the one moved at no-show time, the newest open one,
// then the newest lost or abandoned one. With none of those, a new opportunity is created.
const plan = $('Opportunity Plan').first().json;
const list = ($input.first().json.opportunities || []).filter(o => o && o.pipelineId === String($env.GHL_PIPELINE_ID));
const newest = (a, b) => new Date(b.updatedAt || b.lastStatusChangeAt || b.createdAt || 0) - new Date(a.updatedAt || a.lastStatusChangeAt || a.createdAt || 0);
const preferred = list.find(o => plan.preferredId && o.id === plan.preferredId && o.status !== 'won');
const open = list.filter(o => o.status === 'open').sort(newest)[0];
const old = list.filter(o => o.status === 'lost' || o.status === 'abandoned').sort(newest)[0];
const pick = preferred || open || old;
return [{ json: Object.assign({}, plan, { reuse: Boolean(pick), opportunityId: pick ? pick.id : '', wasStatus: pick ? pick.status : '' }) }];

