// ---- shared secret ----
// The GoHighLevel workflows send it as "Authorization: Bearer <secret>" (Custom Webhook action, Bearer Token).
// The free Webhook action cannot send headers, so a "secret" custom data field is accepted too.
// Fail closed: when GHL_WEBHOOK_SECRET is not set, every call is refused.
function sameSecret(given, expected) {
  // Constant time comparison, so response times do not reveal how much of a guess was right
  given = String(given ?? '');
  let diff = given.length ^ expected.length;
  for (let i = 0; i < expected.length; i++) diff |= (given.charCodeAt(i) || 0) ^ expected.charCodeAt(i);
  return diff === 0;
}
function secretOk(headers, body) {
  const secret = String($env.GHL_WEBHOOK_SECRET ?? '').trim();
  if (!secret) return false;
  const custom = body.customData && typeof body.customData === 'object' ? body.customData : {};
  const bearer = String(headers.authorization ?? '').replace(/^Bearer\s+/i, '').trim();
  return [bearer, String(custom.secret ?? '').trim(), String(body.secret ?? '').trim()].some(v => v !== '' && sameSecret(v, secret));
}

