// ---- picking open times ----
// Free slots come back keyed by date: { "2026-10-27": { "slots": ["2026-10-27T10:00:00-05:00", ...] } }.
// Picks up to 3 times: the patient's preferred days and time of day first, one per day where possible,
// and times they were already offered last. Nothing earlier than notBefore.
function pickTimes(src, o) {
  const box = src && typeof src === 'object' ? src : {};
  const all = [];
  for (const day of Object.keys(box).filter(k => /^\d{4}-\d{2}-\d{2}$/.test(k)).sort()) {
    for (const start of (box[day] && Array.isArray(box[day].slots) ? box[day].slots : [])) {
      const t = new Date(start).getTime();
      if (Number.isFinite(t) && t >= o.notBefore) all.push({ day, start: String(start), t });
    }
  }
  all.sort((a, b) => a.t - b.t);
  const weekday = t => new Intl.DateTimeFormat('en-US', { timeZone: o.tz, weekday: 'short' }).format(new Date(t)).toLowerCase().slice(0, 3);
  const part = o.part || 'any';
  const partOk = t => { const h = localHour(o.tz, new Date(t)); return part === 'morning' ? h < 12 : part === 'afternoon' ? h >= 12 && h < 17 : part === 'evening' ? h >= 17 : true; };
  const days = o.days || [];
  const asked = days.length > 0 || part !== 'any';
  const wanted = all.filter(x => (!days.length || days.includes(weekday(x.t))) && partOk(x.t));
  const pool = wanted.length ? wanted : all;
  const before = new Set(o.avoid || []);
  const pick = [];
  const take = list => { for (const x of list) if (pick.length < 3 && !pick.includes(x)) pick.push(x); };
  const unseen = pool.filter(x => !before.has(x.start));
  take(unseen.filter((x, n) => unseen.findIndex(y => y.day === x.day) === n));
  take(unseen);
  take(pool);
  pick.sort((a, b) => a.t - b.t);
  // End time in the same offset as the start time, which is how GoHighLevel returns slots.
  const endOf = (start, t) => {
    const m = String(start).match(/([+-])(\d{2}):(\d{2})$/);
    if (!m) return new Date(t + o.minutes * 60000).toISOString();
    const off = (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3]));
    return new Date(t + o.minutes * 60000 + off * 60000).toISOString().slice(0, 19) + m[0];
  };
  return { options: pick.map(x => ({ start: x.start, end: endOf(x.start, x.t), label: label(x.t, o.tz) })), matched: !asked || wanted.length > 0 };
}

// New open times for this patient: their preferred days and time of day first, never a time they were already offered
// unless nothing else is open.
const ctx = $('Build Agent Context').first().json;
const d = $('Read Decision').first().json;
const res = $input.first().json || {};
if (res.error) return [{ json: { options: [], matched: true, slotsProblem: String(res.error.message || JSON.stringify(res.error)).slice(0, 300) } }];
const r = pickTimes(res, { tz: ctx.timezone, notBefore: d.notBefore, minutes: ctx.minutes, avoid: ctx.avoid, days: d.days, part: d.part });
return [{ json: { options: r.options, matched: r.matched, slotsProblem: '' } }];

