// ---- tags (TAG_PREFIX, default no-show) ----
const PREFIX = String($env.TAG_PREFIX || 'no-show').trim().toLowerCase();
const TAGS = { active: PREFIX, rebooked: `${PREFIX}-rebooked`, declined: `${PREFIX}-declined`, noReply: `${PREFIX}-no-reply`,
  human: `${PREFIX}-needs-human`, stopped: `${PREFIX}-opted-out`, flag: `${PREFIX}-agent-booked` };

// ---- the agent's memory (workflow static data) ----
const store = $getWorkflowStaticData('global');
// Only what is missing is assigned. n8n writes the memory back after every run that assigns to it, even the same
// value, so runs that only read it (an idle 15 minute run, an ignored reply) must not assign anything.
if (!store.cases) store.cases = {};
if (!store.seenAppointments) store.seenAppointments = {};
if (!store.seenMessages) store.seenMessages = {};
if (!store.log) store.log = [];
const logEvent = (type, c, detail) => {
  store.log.push({ at: new Date().toISOString(), type, contactId: c.contactId || '', name: c.name || '', detail: detail || '' });
  if (store.log.length > 3000) store.log.splice(0, store.log.length - 3000);
};

// ---- small text helpers ----
// Everything that reaches Slack is escaped, so a patient who texts <!channel> cannot ping the channel.
const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const errText = e => String(!e ? 'unknown error' : (typeof e === 'string' ? e : (e.message || JSON.stringify(e)))).slice(0, 300);
const listTimes = opts => opts.map((x, n) => `${n + 1}) ${x.label}`).join('\n');
const askLine = opts => opts.length === 1 ? 'Reply 1 to book' : `Reply ${opts.map((x, n) => n + 1).slice(0, -1).join(', ')} or ${opts.length} to book`;
const contactLink = id => `${String($env.GHL_APP_URL || 'https://app.gohighlevel.com').replace(/\/+$/, '')}/v2/location/${$env.GHL_LOCATION_ID}/contacts/detail/${id}`;

// ---- result of an HTTP node that has an error output (null when it did not run) ----
const resultOf = name => {
  const n = $(name);
  if (!n.isExecuted) return null;
  const bad = n.all(1);
  if (bad.length) return { ok: false, error: errText(bad[0].json.error), json: bad[0].json };
  const good = n.all(0);
  return { ok: true, error: '', json: good.length ? good[0].json : {} };
};

// Every branch ends here. Decides the SMS, the tags, the team alert and whether the run is marked as failed,
// and saves what the agent has to remember about this patient.
const ctx = $('Build Agent Context').first().json;
const decision = $('Read Decision').isExecuted ? $('Read Decision').first().json : null;
const route = decision ? decision.route : ctx.action;
const c = store.cases[ctx.contactId] || {};
const now = new Date().toISOString();
const first = ctx.firstName || 'there';
const who = slackSafe(`${ctx.name} (${ctx.phone})`);
const link = contactLink(ctx.contactId);
const HOLD = `Thanks ${first}! Someone from the clinic will text you back shortly.`;
const o = { sms: '', tagsAdd: [], removeActive: false, alert: '', fail: '', countsAsAi: false, options: null };
// Closing drops any text still waiting for the morning; a text decided below (quiet hours) is set again after this.
const close = (status, tag) => { Object.assign(c, { status, closedAt: now, pending: null }); if (tag) o.tagsAdd.push(tag); o.removeActive = true; logEvent(status, c, ''); };
const needsPerson = why => {
  close('handed_off', TAGS.human);
  o.alert = `*No-show patient needs a person*: ${who}\nThey said: "${slackSafe(ctx.text)}"\n${why}\n${link}`;
};
if (route === 'opt_out') {
  const dnd = resultOf('GHL: Set SMS DND');
  close('opted_out', TAGS.stopped);
  if (dnd && !dnd.ok) o.fail = `URGENT: ${who} asked to stop texts, but GoHighLevel did not accept the DND update. Set DND for SMS by hand now. ${slackSafe(dnd.error)}`;
} else if (route === 'rebooked_elsewhere') {
  // No text: they already have a new visit. A person reads what they wrote and answers if needed.
  close('rebooked_elsewhere', TAGS.rebooked);
  o.alert = `*No-show patient already rebooked*: ${who}\nThey said: "${slackSafe(ctx.text)}"\nThe agent did not answer or book, because ${slackSafe(ctx.reason)}. Reply by hand if needed.\n${link}`;
} else if (route === 'hand_off') {
  o.sms = HOLD;
  needsPerson(`The agent stopped replying because ${ctx.reason}.`);
} else if (route === 'reply' && decision.fallback) {
  // A message with an opt out word in it gets no holding reply: it may be an opt out, and a person decides.
  o.sms = ctx.stopHint ? '' : HOLD;
  const held = ctx.stopHint ? 'Nothing was sent, because the message may ask us to stop texting. Set DND by hand if it does.' : 'They got a holding reply.';
  needsPerson(`Claude could not answer. ${held}`);
  o.fail = `Claude did not give a usable answer for ${who}. ${held} They have the needs-human tag. They wrote "${slackSafe(ctx.text)}". ${decision.failure}. Check ANTHROPIC_API_KEY, your credit balance and ANTHROPIC_MODEL.`;
} else if (route === 'reply') {
  o.sms = decision.reply;
  o.countsAsAi = true;
  if (decision.intent === 'call_or_question') needsPerson(`Agent replied: "${slackSafe(decision.reply)}"\n${slackSafe(decision.summary)}`);
  if (decision.intent === 'not_rebooking') close('declined', TAGS.declined);
} else if (route === 'offer_times') {
  const pick = $('Pick New Times').isExecuted ? $('Pick New Times').first().json : { options: [], slotsProblem: 'not loaded' };
  if (pick.options.length) {
    const intro = pick.matched ? decision.reply : 'Sorry, nothing is open then. These times are free:';
