// ---- settings check ----
function settingsProblems() {
  const p = [];
  const required = { GHL_API_KEY: $env.GHL_API_KEY, GHL_LOCATION_ID: $env.GHL_LOCATION_ID, GHL_CALENDAR_ID: $env.GHL_CALENDAR_ID,
    GHL_PIPELINE_ID: $env.GHL_PIPELINE_ID, GHL_NO_SHOW_STAGE_ID: $env.GHL_NO_SHOW_STAGE_ID, GHL_REBOOKED_STAGE_ID: $env.GHL_REBOOKED_STAGE_ID,
    GHL_WEBHOOK_SECRET: $env.GHL_WEBHOOK_SECRET, ANTHROPIC_API_KEY: $env.ANTHROPIC_API_KEY };
  for (const [k, v] of Object.entries(required)) if (!String(v ?? '').trim()) p.push(`${k} is empty`);
  // The shared secret is all that stands between the internet and texts to patients: no example value, nothing short.
  const secret = String($env.GHL_WEBHOOK_SECRET ?? '').trim();
  if (secret && (secret.length < 16 || secret === 'make-up-a-long-random-string'))
    p.push('GHL_WEBHOOK_SECRET must be your own random string of at least 16 characters, not the example value');
  if (!validTz(BUSINESS_TZ)) p.push(`BUSINESS_TZ "${BUSINESS_TZ}" is not a valid time zone`);
  if (!(Number.isInteger(START) && Number.isInteger(END) && START >= 0 && END <= 24 && START < END))
    p.push(`SEND_HOUR_START (${START}) and SEND_HOUR_END (${END}) must be whole hours from 0 to 24, START before END`);
  if (FOLLOW_UPS === null) p.push(`FOLLOW_UP_HOURS "${FOLLOW_UPS_RAW}" must be empty or up to two increasing numbers of hours, for example 24,72`);
  else if (!(CLOSE_AFTER > (FOLLOW_UPS[FOLLOW_UPS.length - 1] || 0))) p.push(`CLOSE_AFTER_HOURS (${CLOSE_AFTER}) must be later than the last follow-up`);
  // Replies use a forced tool call with thinking off. These models refuse one or both (Anthropic model docs).
  if (/^claude-(fable|mythos|opus-5-5)\b/.test(MODEL))
    p.push(`ANTHROPIC_MODEL ${MODEL} does not accept the forced tool call with thinking off that replies use (use claude-sonnet-5, claude-opus-5 or claude-haiku-4-5)`);
  return p;
}

// Reads the agent's memory and lists what is due now: texts that waited for quiet hours to end, follow-ups for patients
// who never answered, and conversations to close. GoHighLevel is not called here; each patient is reloaded in the loop.
const problems = settingsProblems();
if (problems.length) return [{ json: { route: 'settings', problems } }];
const now = Date.now();
const hoursSince = iso => (iso ? (now - new Date(iso).getTime()) / 3600000 : Infinity);
const sends = [], closes = [];
for (const c of Object.values(store.cases)) {
  if (!c || !c.contactId) continue;
  const tz = validTz(c.timezone) ? c.timezone : BUSINESS_TZ;
  if (c.pending && c.status !== 'opted_out') { if (inWindow(tz)) sends.push({ kind: 'pending', contactId: c.contactId }); continue; }
  if (c.status !== 'waiting') continue;
  if (!c.lastInboundAt && c.firstTextAt) {
    const n = c.followUps || 0;
    // Each step also keeps its own distance from the text before it, so a late follow-up (quiet hours, n8n down) never
    // pulls the next follow-up or the close right behind it.
    const sinceLast = hoursSince(c.lastTextAt || c.firstTextAt);
    if (n < FOLLOW_UPS.length) {
      if (hoursSince(c.firstTextAt) >= FOLLOW_UPS[n] && sinceLast >= FOLLOW_UPS[n] - (n ? FOLLOW_UPS[n - 1] : 0) && inWindow(tz))
        sends.push({ kind: 'followup', number: n + 1, contactId: c.contactId });
      continue;
    }
    if (hoursSince(c.firstTextAt) >= CLOSE_AFTER && sinceLast >= CLOSE_AFTER - (FOLLOW_UPS[FOLLOW_UPS.length - 1] || 0))
      closes.push({ kind: 'close', contactId: c.contactId });
  } else if (c.lastInboundAt) {
    // They answered once and then went quiet.
    const last = [c.lastInboundAt, c.lastTextAt].filter(Boolean).sort().pop();
    if (hoursSince(last) >= CLOSE_AFTER) closes.push({ kind: 'close', contactId: c.contactId });
  } else if (hoursSince(c.openedAt) >= CLOSE_AFTER) {
    // Never texted and nothing waiting: closed, so the patient does not stay "in a conversation" for good.
    closes.push({ kind: 'close', contactId: c.contactId });
  }
}
return sends.slice(0, 25).concat(closes.slice(0, 50)).map(w => ({ json: Object.assign({ route: 'work', number: 0 }, w) }));

