  // 400, 404 or 422 usually means the contact was deleted or merged in GoHighLevel (counted in Record Due Result).
  return out({ action: 'fail', problem: `could not reload the patient: ${why}`, notFound: /^(400|404|422)\b/.test(why) });
}
// .first() would read the error output, the one wired straight to this node, so the success output is read by index.
const contact = ($('GHL: Reload Patient').all(0)[0] || { json: {} }).json.contact || {};
const tags = (contact.tags || []).map(t => String(t).toLowerCase());
const tz = validTz(contact.timezone) ? contact.timezone : BUSINESS_TZ;
const smsStatus = contact.dndSettings && contact.dndSettings.SMS ? contact.dndSettings.SMS.status : '';
if (contact.dnd === true || smsStatus === 'active' || smsStatus === 'permanent' || tags.includes(TAGS.stopped)) {
  return c.status === 'waiting' ? out({ action: 'close', outcome: 'opted_out', tag: TAGS.stopped }) : out({ action: 'drop', why: 'SMS DND is on' });
}
const sendPending = () => (inWindow(tz) ? out({ action: 'send', text: (c.pending || {}).text || '' }) : out({ action: 'wait' }));
// A text the agent decided on as the conversation closed (a booking confirmation, a hand off, a goodbye) still goes out.
if (w.kind === 'pending' && c.status !== 'waiting') return sendPending();
if (inp.error) return out({ action: 'fail', problem: `could not check their appointments: ${String(inp.error.message || 'unknown error').slice(0, 200)}` });
// From here the conversation is open, also for a first text or a reply that waited for the morning.
if (tags.includes(TAGS.human)) return out({ action: 'close', outcome: 'handed_off', tag: TAGS.human });
// Booked another way since the no-show (by phone, online or by the team): the agent stops, and a waiting text is dropped.
const events = Array.isArray(inp.events) ? inp.events : [];
if (laterVisit(events, c.appointmentId, Number.isFinite(c.missedMs) ? c.missedMs : parseWhen(c.missedStart))) {
  return out({ action: 'close', outcome: 'rebooked_elsewhere', tag: TAGS.rebooked });
}
if (w.kind === 'pending') return sendPending();
if (w.kind === 'close') return out({ action: 'close', outcome: 'no_reply', tag: TAGS.noReply });
if (!inWindow(tz)) return out({ action: 'wait' });
const nowMs = Date.now();
return out({ action: 'followup', slotQuery: qs({ startDate: nowMs, endDate: nowMs + SLOT_DAYS * 86400000, timezone: tz, userId: c.staffId }), notBefore: nowMs + 2 * 3600000, timezone: tz });

// ---- settings (all read from $env) ----
const num = (v, d) => { const s = String(v ?? '').trim(); const n = Number(s); return s !== '' && Number.isFinite(n) ? n : d; };
const BUSINESS_TZ = String($env.BUSINESS_TZ || 'America/New_York').trim();
const START = num($env.SEND_HOUR_START, 9);
const END = num($env.SEND_HOUR_END, 19);
const FOLLOW_UPS_RAW = String($env.FOLLOW_UP_HOURS ?? '24,72').trim();
const FOLLOW_UPS = (() => {
  if (!FOLLOW_UPS_RAW) return [];
  const a = FOLLOW_UPS_RAW.split(',').map(x => Number(x.trim()));
  return a.length <= 2 && a.every((x, i) => Number.isFinite(x) && x > 0 && (i === 0 || x > a[i - 1])) ? a : null;
})();
