// ---- picking open times ----
// Free slots come back keyed by date: { "2026-10-27": { "slots": ["2026-10-27T10:00:00-05:00", ...] } }.
// Picks up to 3 times: the patient's preferred days and time of day first, one per day where possible,
// and times they were already offered last. Nothing earlier than notBefore.
function pickTimes(src, o) {
  const box = src && typeof src === 'object' ? src : {};
  const all = [];
  for (const day of Object.keys(box).filter(k => /^\d{4}-\d{2}-\d{2}$/.test(k)).sort()) {
    for (const start of (box[day] && Array.isArray(box[day].slots) ? box[day].slots : [])) {
      const t = new Date(start).getTime();
      if (Number.isFinite(t) && t >= o.notBefore) all.push({ day, start: String(start), t });
    }
  }
  all.sort((a, b) => a.t - b.t);
  const weekday = t => new Intl.DateTimeFormat('en-US', { timeZone: o.tz, weekday: 'short' }).format(new Date(t)).toLowerCase().slice(0, 3);
  const part = o.part || 'any';
  const partOk = t => { const h = localHour(o.tz, new Date(t)); return part === 'morning' ? h < 12 : part === 'afternoon' ? h >= 12 && h < 17 : part === 'evening' ? h >= 17 : true; };
  const days = o.days || [];
  const asked = days.length > 0 || part !== 'any';
  const wanted = all.filter(x => (!days.length || days.includes(weekday(x.t))) && partOk(x.t));
  const pool = wanted.length ? wanted : all;
  const before = new Set(o.avoid || []);
  const pick = [];
  const take = list => { for (const x of list) if (pick.length < 3 && !pick.includes(x)) pick.push(x); };
  const unseen = pool.filter(x => !before.has(x.start));
  take(unseen.filter((x, n) => unseen.findIndex(y => y.day === x.day) === n));
  take(unseen);
  take(pool);
  pick.sort((a, b) => a.t - b.t);
  // End time in the same offset as the start time, which is how GoHighLevel returns slots.
  const endOf = (start, t) => {
    const m = String(start).match(/([+-])(\d{2}):(\d{2})$/);
    if (!m) return new Date(t + o.minutes * 60000).toISOString();
    const off = (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3]));
    return new Date(t + o.minutes * 60000 + off * 60000).toISOString().slice(0, 19) + m[0];
  };
  return { options: pick.map(x => ({ start: x.start, end: endOf(x.start, x.t), label: label(x.t, o.tz) })), matched: !asked || wanted.length > 0 };
}

// Gentle follow-ups for a patient who never answered, with fresh open times. The second one is the last.
const d = $('Check Due Work').first().json;
const c = store.cases[d.contactId] || {};
const res = $input.first().json || {};
const slotsProblem = res.error ? String(res.error.message || JSON.stringify(res.error)).slice(0, 300) : '';
const options = slotsProblem ? [] : pickTimes(res, { tz: d.timezone, notBefore: d.notBefore, minutes: c.minutes || 30, avoid: c.offeredBefore || [], days: [], part: 'any' }).options;
const first = c.firstName || 'there';
const last = d.number >= FOLLOW_UPS.length;
let text = last
  ? `Hi ${first}, one last note from ${BUSINESS}: whenever you are ready to rebook your ${VISIT}, just reply here.`
  : `Hi ${first}, just checking in from ${BUSINESS}. Would you like to rebook your ${VISIT}?`;
text += options.length ? ` These times are open:\n${listTimes(options)}\n${askLine(options)}, or tell us a day that suits you.` : ' Reply with a day and time that suits you.';
if (last) text += ' This is our last reminder about it.';
text += '\nReply STOP to opt out.';
return [{ json: { contactId: d.contactId, text, options, slotsProblem } }];

// ---- tags (TAG_PREFIX, default no-show) ----
const PREFIX = String($env.TAG_PREFIX || 'no-show').trim().toLowerCase();
const TAGS = { active: PREFIX, rebooked: `${PREFIX}-rebooked`, declined: `${PREFIX}-declined`, noReply: `${PREFIX}-no-reply`,
  human: `${PREFIX}-needs-human`, stopped: `${PREFIX}-opted-out`, flag: `${PREFIX}-agent-booked` };

// ---- the agent's memory (workflow static data) ----
const store = $getWorkflowStaticData('global');
// Only what is missing is assigned. n8n writes the memory back after every run that assigns to it, even the same
// value, so runs that only read it (an idle 15 minute run, an ignored reply) must not assign anything.
if (!store.cases) store.cases = {};
if (!store.seenAppointments) store.seenAppointments = {};
if (!store.seenMessages) store.seenMessages = {};
if (!store.log) store.log = [];
const logEvent = (type, c, detail) => {
  store.log.push({ at: new Date().toISOString(), type, contactId: c.contactId || '', name: c.name || '', detail: detail || '' });
  if (store.log.length > 3000) store.log.splice(0, store.log.length - 3000);
};

// ---- small text helpers ----
// Everything that reaches Slack is escaped, so a patient who texts <!channel> cannot ping the channel.
const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const errText = e => String(!e ? 'unknown error' : (typeof e === 'string' ? e : (e.message || JSON.stringify(e)))).slice(0, 300);
const listTimes = opts => opts.map((x, n) => `${n + 1}) ${x.label}`).join('\n');
const askLine = opts => opts.length === 1 ? 'Reply 1 to book' : `Reply ${opts.map((x, n) => n + 1).slice(0, -1).join(', ')} or ${opts.length} to book`;
const contactLink = id => `${String($env.GHL_APP_URL || 'https://app.gohighlevel.com').replace(/\/+$/, '')}/v2/location/${$env.GHL_LOCATION_ID}/contacts/detail/${id}`;

// Saves what happened to this patient and goes back to the loop. Problems are collected and reported after the loop.
const d = $('Check Due Work').first().json;
const c = store.cases[d.contactId];
const inp = $input.first().json || {};
const now = new Date().toISOString();
const who = slackSafe(d.name);
const r = { contactId: d.contactId, name: d.name, action: d.action, outcome: d.outcome || '', problem: '' };
if (!c) return [{ json: Object.assign(r, { problem: `${who}: the case is no longer in the agent's memory` }) }];
if (d.action !== 'fail' && c.lookupMisses) c.lookupMisses = 0;
if (d.action === 'send' || d.action === 'followup') {
  // Compose Follow-up ran in this pass only for a follow-up.
  const composed = d.action === 'followup' ? $('Compose Follow-up').first().json : null;
  const text = composed ? composed.text : d.text;
  const pending = c.pending || {};
  if (inp.error) {
    r.problem = `The ${d.action === 'followup' ? 'follow-up ' + d.number : 'waiting text'} to ${who} was NOT sent: ${slackSafe(String(inp.error.message || 'unknown error').slice(0, 200))}. Text them by hand: "${slackSafe(text)}"`;
    if (d.action === 'followup') c.followUps = d.number;
    else {
      // A first text that never went out ends the conversation, as it does when it fails at no-show time. Otherwise the
      // patient would stay "in a conversation" for good, and their later no-shows would be skipped.
      if (pending.kind === 'first' && c.status === 'waiting') {
        Object.assign(c, { status: 'handed_off', closedAt: now });
        r.problem += ' The agent will not text them about this visit.';
        logEvent('waiting_text_failed', c, '');
      }
      c.pending = null;
    }
  } else if (d.action === 'send') {
    if (pending.kind === 'first') { c.firstTextAt = now; c.offeredAt = now; }
    if (pending.hasOptions) c.offeredAt = now;
    if (pending.countsAsAi) c.aiReplies = (c.aiReplies || 0) + 1;
    c.lastTextAt = now;
    c.pending = null;
    logEvent('waiting_text_sent', c, pending.kind || '');
  } else {
    Object.assign(c, { followUps: d.number, lastTextAt: now });
    if (composed.options.length) Object.assign(c, { offered: composed.options, offeredAt: now, offeredBefore: (c.offeredBefore || []).concat(composed.options.map(x => x.start)).slice(-30) });
    logEvent('follow_up', c, String(d.number));
    if (composed.slotsProblem) r.problem = `Follow-up ${d.number} to ${who} went out without open times, because the calendar could not be loaded (${slackSafe(composed.slotsProblem)}).`;
  }
} else if (d.action === 'close') {
  const add = $('GHL: Add Close Tag').all(1);
  Object.assign(c, { status: d.outcome, closedAt: now, pending: null });
  logEvent(d.outcome, c, 'closed by the schedule');
  const notes = [];
  if (add.length) notes.push(`the ${d.tag} tag was not added (${slackSafe(String(add[0].json.error.message || '').slice(0, 200))})`);
  if (inp.error) notes.push(`the ${TAGS.active} tag was not removed (${slackSafe(String(inp.error.message || '').slice(0, 200))}), so GoHighLevel keeps forwarding their texts (the agent ignores them)`);
  if (notes.length) r.problem = `Closed the conversation with ${who} (${d.outcome}), but ${notes.join(' and ')}. Fix the tags by hand.`;
} else if (d.action === 'drop') {
  c.pending = null;
} else if (d.action === 'fail') {
  // A contact GoHighLevel cannot find (deleted or merged) would fail every 15 minutes for good. After 3 misses in a row
  // the agent lets go. Other errors (token, outage) are retried and reported every time.
  c.lookupMisses = d.notFound ? (c.lookupMisses || 0) + 1 : 0;
  if (c.lookupMisses >= 3) {
    Object.assign(c, { status: 'handed_off', closedAt: now, pending: null });
    logEvent('handed_off', c, 'contact not found');
    r.problem = `${who}: GoHighLevel did not find this contact in 3 runs in a row (${slackSafe(d.problem)}), so the agent stopped and will not text them again. Check whether the contact was deleted or merged.`;
  } else {
    r.problem = `${who}: ${slackSafe(d.problem)}. Nothing was sent; the schedule tries again in 15 minutes.`;
  }
}
return [{ json: r }];

// After the loop: one line per problem, so a single failed run lists everything that needs a person.
const rows = $input.all().map(i => i.json);
const problems = rows.map(r => r.problem).filter(Boolean);
return [{ json: { handled: rows.length, sent: rows.filter(r => ['send', 'followup'].includes(r.action) && !r.problem).length,
  closed: rows.filter(r => r.action === 'close').length, fail: problems.length ? 'Scheduled run: ' + problems.join(' ') : '' } }];

