// ---- small text helpers ----
// Everything that reaches Slack is escaped, so a patient who texts <!channel> cannot ping the channel.
const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const errText = e => String(!e ? 'unknown error' : (typeof e === 'string' ? e : (e.message || JSON.stringify(e)))).slice(0, 300);
const listTimes = opts => opts.map((x, n) => `${n + 1}) ${x.label}`).join('\n');
const askLine = opts => opts.length === 1 ? 'Reply 1 to book' : `Reply ${opts.map((x, n) => n + 1).slice(0, -1).join(', ')} or ${opts.length} to book`;
