// One Slack message a day about the last 24 hours, from the agent's memory. Also forgets old closed cases.
const now = Date.now();
const recent = store.log.filter(e => now - new Date(e.at).getTime() < 24 * 3600000);
const of = type => recent.filter(e => e.type === type);
const names = list => list.map(e => slackSafe(e.name)).filter(Boolean).slice(0, 8).join(', ');
const skipped = of('no_show_skipped');
const reasons = {};
for (const e of skipped) reasons[e.detail] = (reasons[e.detail] || 0) + 1;
const texted = of('no_show_texted').length, queued = of('no_show_queued').length;
const failed = of('no_show_failed').length;
const total = texted + queued + failed + skipped.length;
const rebooked = of('rebooked'), elsewhere = of('rebooked_elsewhere'), handed = of('handed_off');
const waiting = Object.values(store.cases).filter(c => c.status === 'waiting');
const lines = [
  `*No-show rebooking, last 24 hours* (${slackSafe(BUSINESS)})`,
  `No-shows: ${total} (${texted} texted at once${queued ? `, ${queued} held for the morning` : ''}${failed ? `, ${failed} text failed` : ''}${skipped.length ? `, ${skipped.length} not texted: ${Object.entries(reasons).map(([r, n]) => `${n} ${slackSafe(r)}`).join(', ')}` : ''})`,
  `Rebooked by text: ${rebooked.length}${rebooked.length ? ` (${names(rebooked)})` : ''}${elsewhere.length ? `. Booked another way: ${elsewhere.length}` : ''}`,
  `Waiting for an answer: ${waiting.length} (follow-ups sent: ${of('follow_up').length})`,
  `Handed to a person: ${handed.length}${handed.length ? ` (${names(handed)})` : ''}`,
  `Did not want to rebook: ${of('declined').length}. No reply after follow-ups: ${of('no_reply').length}. Opted out: ${of('opted_out').length}.`,
];
// Housekeeping: closed cases and log lines older than 30 days are forgotten.
for (const [id, c] of Object.entries(store.cases)) if (c.status !== 'waiting' && (!c.pending || c.status === 'opted_out') && now - new Date(c.closedAt || c.openedAt || 0).getTime() > 30 * 86400000) delete store.cases[id];
store.log = store.log.filter(e => now - new Date(e.at).getTime() < 30 * 86400000);
return [{ json: { text: lines.join('\n'), post: Boolean($env.SLACK_WEBHOOK_URL) } }];
